<?php
defined( 'ABSPATH' ) || exit;
final class HE_Admin {
	public function hooks() { add_action( 'admin_menu', array( $this, 'menu' ) ); add_action( 'admin_post_he_review_entry', array( $this, 'review' ) ); add_action( 'admin_post_he_resolve_feedback', array( $this, 'resolve' ) ); add_action( 'admin_notices', array( $this, 'notice' ) ); }
	public function menu() { add_menu_page( 'Encyclopedia Management', 'Encyclopedia Management', 'manage_homeopathy_encyclopedia', 'encyclopedia-management', array( $this, 'dashboard' ), 'dashicons-book-alt', 30 ); add_submenu_page( 'encyclopedia-management', 'Entry Moderation', 'Entry Moderation', 'manage_homeopathy_encyclopedia', 'encyclopedia-management', array( $this, 'dashboard' ) ); add_submenu_page( 'encyclopedia-management', 'Corrections and Reports', 'Corrections and Reports', 'manage_homeopathy_encyclopedia', 'encyclopedia-feedback', array( $this, 'feedback' ) ); add_submenu_page( 'encyclopedia-management', 'All Entries', 'All Entries', 'manage_homeopathy_encyclopedia', 'edit.php?post_type=' . HE_Content::TYPE ); add_submenu_page( 'encyclopedia-management', 'Comments', 'Comments', 'manage_homeopathy_encyclopedia', 'edit-comments.php' ); }
	public function dashboard() { $this->guard(); $status = isset( $_GET['entry_status'] ) ? sanitize_key( wp_unslash( $_GET['entry_status'] ) ) : 'pending'; if ( ! in_array( $status, array( 'pending', 'publish', 'draft', 'private' ), true ) ) { $status = 'pending'; } $entries = get_posts( array( 'post_type' => HE_Content::TYPE, 'post_status' => $status, 'posts_per_page' => 100, 'orderby' => 'date', 'order' => 'DESC' ) ); ?>
		<div class="wrap he-admin"><h1>Encyclopedia Management</h1><p>Review American English, references, author identity, relationships, copyright, medical red flags, safety, and unsupported claims.</p><nav><?php foreach ( array( 'pending' => 'Pending', 'publish' => 'Published', 'draft' => 'Rejected / Draft', 'private' => 'Hidden' ) as $key => $label ) : ?><a class="<?php echo $status === $key ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'page' => 'encyclopedia-management', 'entry_status' => $key ), admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html( $label ); ?></a><?php endforeach; ?></nav><table class="widefat striped"><thead><tr><th>Entry</th><th>Type and author</th><th>Safety</th><th>Review</th></tr></thead><tbody><?php if ( $entries ) : foreach ( $entries as $entry ) : ?><tr><td><strong><?php echo esc_html( $entry->post_title ); ?></strong><p><?php echo esc_html( $entry->post_excerpt ); ?></p><details><summary>Review full entry</summary><div class="he-admin-content"><?php echo wp_kses_post( wpautop( $entry->post_content ) ); ?><h4>References</h4><?php echo nl2br( esc_html( HE_Content::meta( $entry->ID, 'references' ) ) ); ?></div></details></td><td><?php echo esc_html( HE_Content::type( $entry->ID ) ); ?><br><?php echo esc_html( get_the_author_meta( 'display_name', $entry->post_author ) ); ?><br><?php echo esc_html( HE_Permissions::label( $entry->post_author ) ); ?></td><td><strong>Red flags:</strong> <?php echo HE_Content::meta( $entry->ID, 'red_flags' ) ? 'Present' : 'Not added'; ?><br><strong>Safety:</strong> <?php echo HE_Content::meta( $entry->ID, 'safety' ) ? 'Present' : 'Not added'; ?><br><strong>Language:</strong> <?php echo esc_html( HE_Content::meta( $entry->ID, 'language' ) ?: 'Not set' ); ?></td><td><?php echo $this->review_form( $entry ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></td></tr><?php endforeach; else : ?><tr><td colspan="4">No entries in this view.</td></tr><?php endif; ?></tbody></table></div><?php }
	private function review_form( $entry ) { ob_start(); ?><form class="he-review" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" method="post"><input type="hidden" name="action" value="he_review_entry"><input type="hidden" name="entry_id" value="<?php echo absint( $entry->ID ); ?>"><?php wp_nonce_field( 'he_review_' . $entry->ID ); ?><select name="review_action"><option value="approve">Approve and publish</option><option value="reject">Reject to draft</option><option value="hide">Hide entry</option></select><textarea name="note" rows="3" placeholder="Internal review note"></textarea><button class="button button-primary" type="submit">Apply</button></form><?php return ob_get_clean(); }
	public function review() { $this->guard(); $id = isset( $_POST['entry_id'] ) ? absint( $_POST['entry_id'] ) : 0; check_admin_referer( 'he_review_' . $id ); $entry = get_post( $id ); $action = isset( $_POST['review_action'] ) ? sanitize_key( wp_unslash( $_POST['review_action'] ) ) : ''; $note = isset( $_POST['note'] ) ? sanitize_textarea_field( wp_unslash( $_POST['note'] ) ) : ''; if ( ! $entry || HE_Content::TYPE !== $entry->post_type || ! in_array( $action, array( 'approve', 'reject', 'hide' ), true ) ) { wp_die( esc_html__( 'Invalid review request.', 'homeopathy-encyclopedia' ), '', array( 'response' => 400 ) ); } if ( 'approve' === $action ) { $type = HE_Content::type( $id, 'slug' ); if ( ! HE_Content::allowed( $type ) || ! trim( HE_Content::meta( $id, 'references' ) ) || 'en-US' !== HE_Content::meta( $id, 'language' ) ) { wp_die( esc_html__( 'Approved type, references, or American English language metadata is missing.', 'homeopathy-encyclopedia' ), '', array( 'response' => 400 ) ); } if ( in_array( $type, array( 'health-condition', 'pathology' ), true ) && ! trim( HE_Content::meta( $id, 'red_flags' ) ) ) { wp_die( esc_html__( 'Medical red flags are required.', 'homeopathy-encyclopedia' ), '', array( 'response' => 400 ) ); } if ( 'remedy' === $type && ! trim( HE_Content::meta( $id, 'safety' ) ) ) { wp_die( esc_html__( 'Remedy safety and limitations are required.', 'homeopathy-encyclopedia' ), '', array( 'response' => 400 ) ); } if ( ! HE_Permissions::is_founder( $entry->post_author ) && ! user_can( $entry->post_author, 'manage_homeopathy_encyclopedia' ) && ! HE_Permissions::is_doctor( $entry->post_author ) ) { wp_die( esc_html__( 'The author is no longer approved.', 'homeopathy-encyclopedia' ), '', array( 'response' => 400 ) ); } update_post_meta( $id, '_he_reviewer_id', get_current_user_id() ); wp_update_post( array( 'ID' => $id, 'post_status' => 'publish' ) ); } elseif ( 'reject' === $action ) { update_post_meta( $id, '_he_review_note', $note ); wp_update_post( array( 'ID' => $id, 'post_status' => 'draft' ) ); } else { wp_update_post( array( 'ID' => $id, 'post_status' => 'private' ) ); } self::audit( $id, $action, $note ); wp_safe_redirect( admin_url( 'admin.php?page=encyclopedia-management' ) ); exit; }
	public function feedback() { $this->guard(); global $wpdb; $items = $wpdb->get_results( "SELECT * FROM {$wpdb->prefix}he_feedback WHERE status='open' ORDER BY created_at DESC LIMIT 200" ); ?><div class="wrap he-admin"><h1>Corrections and Reports</h1><table class="widefat striped"><thead><tr><th>Entry</th><th>Kind</th><th>Reason</th><th>Details</th><th>Action</th></tr></thead><tbody><?php if ( $items ) : foreach ( $items as $item ) : ?><tr><td><a href="<?php echo esc_url( get_permalink( $item->entry_id ) ); ?>" target="_blank" rel="noopener"><?php echo esc_html( get_the_title( $item->entry_id ) ); ?></a></td><td><?php echo esc_html( ucfirst( $item->kind ) ); ?></td><td><?php echo esc_html( ucwords( str_replace( '-', ' ', $item->reason ) ) ); ?></td><td><?php echo esc_html( $item->details ); ?></td><td><form action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" method="post"><input type="hidden" name="action" value="he_resolve_feedback"><input type="hidden" name="feedback_id" value="<?php echo absint( $item->id ); ?>"><?php wp_nonce_field( 'he_resolve_' . $item->id ); ?><button class="button" type="submit">Mark Resolved</button></form></td></tr><?php endforeach; else : ?><tr><td colspan="5">No open submissions.</td></tr><?php endif; ?></tbody></table></div><?php }
	public function resolve() { $this->guard(); global $wpdb; $id = isset( $_POST['feedback_id'] ) ? absint( $_POST['feedback_id'] ) : 0; check_admin_referer( 'he_resolve_' . $id ); $wpdb->update( $wpdb->prefix . 'he_feedback', array( 'status' => 'resolved' ), array( 'id' => $id ), array( '%s' ), array( '%d' ) ); wp_safe_redirect( admin_url( 'admin.php?page=encyclopedia-feedback' ) ); exit; }
	public static function audit( $id, $action, $note ) { global $wpdb; $wpdb->insert( $wpdb->prefix . 'he_audit_log', array( 'entry_id' => absint( $id ), 'actor_id' => get_current_user_id(), 'action' => sanitize_key( $action ), 'note' => sanitize_textarea_field( $note ), 'created_at' => current_time( 'mysql', true ) ), array( '%d', '%d', '%s', '%s', '%s' ) ); }
	private function guard() { if ( ! current_user_can( 'manage_homeopathy_encyclopedia' ) ) { wp_die( esc_html__( 'You cannot manage encyclopedia entries.', 'homeopathy-encyclopedia' ), '', array( 'response' => 403 ) ); } }
	public function notice() { if ( current_user_can( 'manage_homeopathy_encyclopedia' ) && get_transient( 'he_activation_notice' ) ) { delete_transient( 'he_activation_notice' ); echo '<div class="notice notice-success is-dismissible"><p><strong>Encyclopedia Foundation is active.</strong> Review the public Encyclopedia and Encyclopedia Management dashboard.</p></div>'; } }
}

